mapper.select:
SELECT ss.id, ss.course_id, ss.student_id, ss.status, ss.select_time, c.course_name AS course_name, stu.student_name AS student_name, stu.college AS college, stu.class_name AS class_name, stu.grade AS grade FROM tb_student_selection ss INNER JOIN tb_course c ON ss.course_id = c.id INNER JOIN tb_student stu ON ss.student_id = stu.id
AND ss.student_id = #{studentId}
AND ss.course_id IN #{courseId}
AND ss.status = #{status} AND c.course_name LIKE CONCAT('%', #{courseName}, '%') AND stu.student_name LIKE CONCAT('%', #{studentName}, '%') AND stu.college = #{college} AND stu.grade = #{grade} AND stu.class_name LIKE CONCAT('%', #{className}, '%') AND DATE(ss.select_time) = DATE(#{selectTime})

mapper.update:
update tb_student_selection
course_id = #{courseId}, student_id = #{studentId}, status = #{status}, select_time = #{selectTime},
where id = #{id}
